    synchronizedWeight nodes t k =
      synchronizedWeight nodes t j *
        ∏ i ∈ Finset.Ico j.val k.val, clockForwardFactorNat nodes i

lemma synchronizedWeight_eq_mul_prod_backward {n : ℕ}
